public struct AssistToolCatalogEntry: Sendable, Hashable {
    public let id: String
    public let name: String
    public let summary: String
    public let sourceType: String

    public init(id: String, name: String, summary: String, sourceType: String) {
        self.id = id
        self.name = name
        self.summary = summary
        self.sourceType = sourceType
    }
}

